package com.nextaicommerce.platform.fba;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.util.*;import java.time.*;import java.net.*;import java.nio.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.concurrent.Flow;
import org.apache.pdfbox.pdmodel.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
import com.nextaicommerce.platform.shipping.ShippingLabelCrypto;
import static com.nextaicommerce.platform.fba.FbaInboundWorkflow.*;
class FbaInboundDocumentsTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),plan=UUID.randomUUID(),warehouse=UUID.randomUUID();final Scope scope=new Scope(tenant,tenant,store,plan);
 final JdbcTemplate jdbc=mock(JdbcTemplate.class);final FbaInboundOrchestration.Checkpoints checkpoints=mock(FbaInboundOrchestration.Checkpoints.class);final ShippingLabelCrypto crypto=new ShippingLabelCrypto(Base64.getEncoder().encodeToString(new byte[32]));
 final FbaInboundDocuments.Download download=mock(FbaInboundDocuments.Download.class);final AtomicReference<Map<String,Object>> saved=new AtomicReference<>();final AtomicReference<FbaInboundOrchestration.Checkpoint> state=new AtomicReference<>();
 FbaInboundDocuments documents;byte[] fixture;
 static byte[] pdf(int pages)throws Exception{try(var doc=new PDDocument();var out=new ByteArrayOutputStream()){for(int i=0;i<pages;i++)doc.addPage(new PDPage());doc.save(out);return out.toByteArray();}}
 FbaInboundOrchestration.Checkpoint checkpoint(long version){UUID request=UUID.randomUUID();var attempt=new Attempt(request,FbaInboundAdapter.Operation.CONFIRM_TRANSPORT,"child",version,"transport",Status.SUCCEEDED,"genuine-operation");return new FbaInboundOrchestration.Checkpoint(new Origin(scope,warehouse,version,"remote-plan",Map.of(request,attempt),Map.of("child",new Child("child",Map.of("SKU",2))),Map.of(),List.of()),Map.of(),Map.of("transport",new FbaInboundOrchestration.Option("transport",FbaInboundAdapter.Operation.CONFIRM_TRANSPORT,version,Instant.now().plusSeconds(300),java.math.BigDecimal.ZERO,"USD",List.of("child"),"child","{}")));}
 @BeforeEach void setup()throws Exception{
  fixture=pdf(1);state.set(checkpoint(1));when(checkpoints.read(scope,warehouse)).thenAnswer(i->new FbaInboundOrchestration.Snapshot(1,state.get()));
  var manager=mock(PlatformTransactionManager.class);when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());var tx=new TransactionTemplate(manager);
  documents=new FbaInboundDocuments(jdbc,tx,crypto,checkpoints,true,true,download);when(download.pdf(any())).thenAnswer(i->fixture.clone());
  when(jdbc.queryForObject(startsWith("SELECT id FROM fba_replenishment_plans"),eq(UUID.class),any(Object[].class))).thenReturn(plan);
  when(jdbc.update(startsWith("INSERT INTO fba_replenishment_documents"),any(Object[].class))).thenAnswer(i->{Object[] a=(Object[])i.getRawArguments()[1];if(saved.get()!=null)return 0;var row=new HashMap<String,Object>();row.put("id",a[0]);row.put("amazon_shipment_id",a[5]);row.put("packing_version",a[6]);row.put("document_type",a[7]);row.put("sha256",a[8]);row.put("encrypted_payload",a[9]);row.put("encryption_nonce",a[10]);row.put("mime_type","application/pdf");saved.set(row);return 1;});
  when(jdbc.queryForObject(startsWith("SELECT id FROM fba_replenishment_documents"),eq(UUID.class),any(Object[].class))).thenAnswer(i->saved.get().get("id"));
  when(jdbc.queryForList(startsWith("SELECT id,amazon_shipment_id"),any(Object[].class))).thenAnswer(i->saved.get()==null?List.of():List.of(saved.get()));
 }
 void register(UUID id){var cp=state.get();var origin=cp.origin();var request=origin.attempts().keySet().iterator().next();state.set(new FbaInboundOrchestration.Checkpoint(issuedDocument(origin,request,"child",id.toString(),DocumentKind.SHIPPING_LABEL),cp.acknowledgements(),cp.options()));}
 @Test void genuineFixtureIsEncryptedScopedAndReprintsWithoutRemoteDownload(){UUID id=UUID.fromString(documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued")));assertFalse(Arrays.equals(fixture,(byte[])saved.get().get("encrypted_payload")));register(id);var stored=documents.read(scope,warehouse,id);assertArrayEquals(fixture,stored.payload());assertFalse(stored.stale());verify(download,times(1)).pdf(any());}
 @Test void repeatedSameGenuineBytesDoNotOverwritePriorVersion(){String first=documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued"));String again=documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued2"));assertEquals(first,again);assertArrayEquals(fixture,documents.read(scope,warehouse,UUID.fromString(first)).payload());}
 @Test void localGuardsBlockBeforeCheckpointOrNetwork(){var tx=new TransactionTemplate(mock(PlatformTransactionManager.class));var disabled=new FbaInboundDocuments(jdbc,tx,crypto,checkpoints,false,false,download);assertThrows(IllegalStateException.class,()->disabled.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued")));verifyNoInteractions(download,checkpoints);}
 @Test void staleVersionBlocksBeforeDownload(){assertThrows(IllegalStateException.class,()->documents.ingest(scope,warehouse,"child",2,URI.create("https://labels.amazon.com/issued")));verifyNoInteractions(download);}
 @Test void artifactMetadataTamperingFailsAuthentication(){UUID id=UUID.fromString(documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued")));saved.get().put("amazon_shipment_id","another-child");assertThrows(IllegalStateException.class,()->documents.read(scope,warehouse,id));}
 @Test void historicPackingDocumentIsRetainedAndMarkedStale(){UUID id=UUID.fromString(documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued")));state.set(checkpoint(2));assertTrue(documents.read(scope,warehouse,id).stale());}
 @Test void nonPdfAndOversizedOrUnreasonablePdfAreRejected()throws Exception{assertThrows(IllegalArgumentException.class,()->FbaInboundDocuments.validatePdf("<html>error</html>".getBytes()));assertThrows(IllegalArgumentException.class,()->FbaInboundDocuments.validatePdf(new byte[FbaInboundDocuments.MAX_BYTES+1]));assertThrows(IllegalArgumentException.class,()->FbaInboundDocuments.validatePdf(pdf(201)));}
 @Test void exactReviewedAmazonHostOnlyWithHttpsNoCredentialsOrAlternatePort(){var client=new FbaInboundDocuments.AmazonDownload("labels.amazon.com");assertDoesNotThrow(()->client.validate(URI.create("https://labels.amazon.com/label?token=fixture")));for(String url:List.of("http://labels.amazon.com/a","https://labels.amazon.com.evil.test/a","https://user@labels.amazon.com/a","https://labels.amazon.com:8443/a","https://labels.amazon.com/a#fragment","https://127.0.0.1/a"))assertThrows(IllegalArgumentException.class,()->client.validate(URI.create(url)));assertThrows(IllegalArgumentException.class,()->new FbaInboundDocuments.AmazonDownload("*.amazonaws.com"));}
 @Test void emptyHostConfigurationFailsClosedWithoutNetwork(){var client=new FbaInboundDocuments.AmazonDownload("");assertThrows(IllegalArgumentException.class,()->client.pdf(URI.create("https://labels.amazon.com/a")));}
 @Test void privateLinkLocalMetadataAndReservedAddressesAreBlocked()throws Exception{for(String value:List.of("127.0.0.1","10.0.0.1","169.254.169.254","100.64.0.1","192.168.1.1","::1","fc00::1","fe80::1","2001:db8::1","::10.0.0.1"))assertFalse(FbaInboundDocuments.AmazonDownload.publicAddress(InetAddress.getByName(value)),value);assertTrue(FbaInboundDocuments.AmazonDownload.publicAddress(InetAddress.getByName("8.8.8.8")));}
 @Test void bodySubscriberCancelsBeforeExceedingByteLimit(){var body=new FbaInboundDocuments.LimitedBody();var sub=mock(Flow.Subscription.class);body.onSubscribe(sub);body.onNext(List.of(ByteBuffer.wrap(new byte[FbaInboundDocuments.MAX_BYTES+1])));assertThrows(CompletionException.class,()->body.getBody().toCompletableFuture().join());verify(sub).cancel();}
 @Test void cancelledShipmentCannotIssueNewCurrentDocuments(){var old=state.get().origin();UUID id=UUID.randomUUID();var attempts=new HashMap<>(old.attempts());attempts.put(id,new Attempt(id,FbaInboundAdapter.Operation.CANCEL,null,1,null,Status.SUCCEEDED,"cancel-operation"));state.set(new FbaInboundOrchestration.Checkpoint(new Origin(scope,warehouse,1,old.amazonPlanId(),attempts,old.children(),old.quotes(),old.documents()),Map.of(),Map.of()));assertThrows(IllegalStateException.class,()->documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued")));verifyNoInteractions(download);}
 @Test void unregisteredArtifactRemainsHistorical(){UUID id=UUID.fromString(documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued")));assertTrue(documents.read(scope,warehouse,id).stale());}
 @Test void changedConfirmationMakesPreviouslyRegisteredDocumentHistorical(){UUID id=UUID.fromString(documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued")));register(id);assertFalse(documents.read(scope,warehouse,id).stale());var cp=checkpoint(1);state.set(new FbaInboundOrchestration.Checkpoint(cp.origin(),cp.acknowledgements(),cp.options()));assertTrue(documents.read(scope,warehouse,id).stale());}
 @Test void unsupportedItemLabelFailsBeforeDownload(){assertThrows(IllegalArgumentException.class,()->documents.ingest(scope,warehouse,"child",1,URI.create("https://labels.amazon.com/issued"),DocumentKind.ITEM_LABEL));verifyNoInteractions(download);}
}

